SET ROLE talus_fn;
CREATE TABLE app.booking_customer(tenant_id uuid NOT NULL,booking_id uuid NOT NULL,customer_id uuid NOT NULL,PRIMARY KEY(tenant_id,booking_id),FOREIGN KEY(tenant_id,booking_id) REFERENCES app.booking(tenant_id,booking_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES app.customer(tenant_id,customer_id));
CREATE TABLE app.customer_booking_access_token(tenant_id uuid NOT NULL,customer_booking_access_token_id uuid NOT NULL DEFAULT gen_random_uuid(),booking_id uuid NOT NULL,booking_item_id uuid NOT NULL,customer_id uuid NOT NULL,token_hash bytea NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,customer_booking_access_token_id),UNIQUE(tenant_id,token_hash),FOREIGN KEY(tenant_id,booking_id) REFERENCES app.booking(tenant_id,booking_id),FOREIGN KEY(tenant_id,booking_item_id) REFERENCES app.booking_item(tenant_id,booking_item_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES app.customer(tenant_id,customer_id),CHECK(expires_at>created_at));
ALTER TABLE app.booking_customer ENABLE ROW LEVEL SECURITY;ALTER TABLE app.booking_customer FORCE ROW LEVEL SECURITY;ALTER TABLE app.customer_booking_access_token ENABLE ROW LEVEL SECURITY;ALTER TABLE app.customer_booking_access_token FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_context_policy ON app.booking_customer USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid());
CREATE POLICY tenant_context_policy ON app.customer_booking_access_token USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid());
CREATE OR REPLACE FUNCTION app.create_public_reservation(p_customer uuid,p_category_location uuid,p_start timestamptz,p_end timestamptz) RETURNS TABLE(booking_id uuid,booking_item_id uuid,access_token uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid; b uuid:=gen_random_uuid();i uuid:=gen_random_uuid();bt uuid:=gen_random_uuid();it uuid:=gen_random_uuid();tok uuid:=gen_random_uuid();l uuid;BEGIN SELECT tenant_id,location_id INTO t,l FROM app.category_location WHERE category_location_id=p_category_location AND active LIMIT 1;IF t IS NULL OR p_end<=p_start OR NOT EXISTS(SELECT 1 FROM app.customer WHERE tenant_id=t AND customer_id=p_customer) THEN RAISE EXCEPTION 'PUBLIC_RESERVATION_INPUT_INVALID' USING ERRCODE='P0001';END IF;INSERT INTO app.booking(tenant_id,booking_id,booking_reference,pickup_location_id,return_location_id,state)VALUES(t,b,'WEB-'||substr(b::text,1,8),l,l,'draft');INSERT INTO app.booking_terms_revision(tenant_id,booking_terms_revision_id,booking_id,revision_number)VALUES(t,bt,b,1);INSERT INTO app.booking_item(tenant_id,booking_item_id,booking_id,item_number,state)VALUES(t,i,b,1,'reserved');INSERT INTO app.booking_item_terms_revision(tenant_id,booking_item_terms_revision_id,booking_item_id,booking_id,booking_terms_revision_id,category_location_id,revision_number,scheduled_start_at,scheduled_end_at,chargeable_day_count)VALUES(t,it,i,b,bt,p_category_location,1,p_start,p_end,GREATEST(1,p_end::date-p_start::date));UPDATE app.booking_item SET current_terms_revision_id=it WHERE tenant_id=t AND booking_item_id=i;INSERT INTO app.booking_customer VALUES(t,b,p_customer);INSERT INTO app.booking_driver VALUES(t,i,p_customer,true);INSERT INTO app.customer_booking_access_token(tenant_id,booking_id,booking_item_id,customer_id,token_hash,expires_at)VALUES(t,b,i,p_customer,public.digest(tok::text,'sha256'),clock_timestamp()+interval '48 hours');RETURN QUERY SELECT b,i,tok;END;$$;
CREATE OR REPLACE FUNCTION app.public_waiver_context(p_token uuid) RETURNS TABLE(booking_item_id uuid,customer_name text,vehicle_name text,waiver_text text) LANGUAGE sql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ SELECT a.booking_item_id,c.display_name,COALESCE(p.display_name,'Side-by-Side'),'Standard Powersports Liability & Damage Waiver v1.0' FROM app.customer_booking_access_token a JOIN app.customer c ON c.tenant_id=a.tenant_id AND c.customer_id=a.customer_id JOIN app.booking_item_terms_revision it ON it.tenant_id=a.tenant_id AND it.booking_item_id=a.booking_item_id JOIN app.rental_product p ON p.tenant_id=it.tenant_id AND p.category_location_id=it.category_location_id WHERE a.token_hash=public.digest(p_token::text,'sha256') AND a.expires_at>clock_timestamp() AND a.used_at IS NULL ORDER BY it.revision_number DESC LIMIT 1; $$;
CREATE OR REPLACE FUNCTION app.submit_public_waiver(p_token uuid,p_name text,p_signature text,p_ip inet) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE a app.customer_booking_access_token%ROWTYPE; pol uuid; w uuid:=gen_random_uuid();BEGIN SELECT * INTO a FROM app.customer_booking_access_token WHERE token_hash=public.digest(p_token::text,'sha256') AND expires_at>clock_timestamp() AND used_at IS NULL FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'WAIVER_ACCESS_INVALID' USING ERRCODE='P0001';END IF;SELECT tenant_waiver_policy_id INTO pol FROM app.tenant_waiver_policy WHERE tenant_id=a.tenant_id ORDER BY version_number DESC LIMIT 1;IF pol IS NULL OR length(btrim(p_name))=0 OR length(btrim(p_signature))=0 THEN RAISE EXCEPTION 'WAIVER_INPUT_INVALID' USING ERRCODE='P0001';END IF;INSERT INTO app.executed_waiver VALUES(a.tenant_id,w,a.customer_id,a.booking_item_id,pol,clock_timestamp(),p_name,p_ip,p_signature,encode(public.digest(p_signature,'sha256'),'hex'));UPDATE app.customer_booking_access_token SET used_at=clock_timestamp() WHERE tenant_id=a.tenant_id AND customer_booking_access_token_id=a.customer_booking_access_token_id;RETURN w;END;$$;
GRANT SELECT,INSERT,UPDATE,DELETE ON app.booking_customer,app.customer_booking_access_token TO talus_fn;REVOKE ALL ON app.booking_customer,app.customer_booking_access_token FROM PUBLIC,talus_staff,talus_api,talus_customer;GRANT EXECUTE ON FUNCTION app.create_public_reservation(uuid,uuid,timestamptz,timestamptz),app.public_waiver_context(uuid),app.submit_public_waiver(uuid,text,text,inet) TO PUBLIC;RESET ROLE;
